// Evaluates historical accuracy of published PEN=X (USD/PEN) daily forecasts against official BCRP closes.
// Source of truth: data/daily-forecasts.json (generated by engine-daily.js, committed daily via official-data.yml).
// Output: data/official/aciertos-dolar.json with per-type stats and prueba_historica block.

import fs from "fs";
import path from "path";
import { fileURLToPath } from "url";
import { addBusinessDays, PERU_HOLIDAYS } from "./engine-daily.js";

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const DAILY_FORECASTS_PATH = path.join(ROOT, "data", "daily-forecasts.json");
const BCRP_PATH = path.join(ROOT, "data", "official", "bcrp-daily.json");
const PRONOSTICOS_PATH = path.join(ROOT, "data", "official", "pronosticos-dolar.json");
const OUTPUT_PATH = path.join(ROOT, "data", "official", "aciertos-dolar.json");
const PRUEBA_HISTORICA_PATH = path.join(ROOT, "research", "v7", "auditoria-real", "resultados-diario-real.json");

/**
 * Pure function: evaluates published forecasts against actual BCRP closes.
 * @param {Array<Object>} pronosticos - Array of {tipo, fecha_publicacion, fecha_base, cierre_base, horizonte_dias_habiles, fecha_objetivo, p10, p50, p90}
 * @param {Array<[string, number]>} officialSerie - BCRP daily series [[date, close], ...]
 * @returns {Object} Result per type with stats, last 60 cases, and prueba_historica
 */
export function evaluatePublishedForecasts(pronosticos, officialSerie) {
  const officialMap = new Map(officialSerie.map(([d, c]) => [d, c]));

  const today = new Intl.DateTimeFormat("en-CA", {
    timeZone: "America/Lima",
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
  }).format(new Date());

  const result = {};

  for (const tipo of ["manana", "semana"]) {
    const relevant = pronosticos.filter((p) => p.tipo === tipo);

    const cases = [];
    let n = 0;
    let dentro = 0;
    let errorMedioCentro = 0;
    let errorMedioPaseoAleatorio = 0;

    for (const p of relevant) {
      const actualClose = officialMap.get(p.fecha_objetivo);

      if (!Number.isFinite(actualClose) || !Number.isFinite(Number(p.p50))) {
        continue;
      }

      n++;
      const p10 = Number(p.p10.toFixed(3));
      const p50 = Number(p.p50);
      const p90 = Number(p.p90.toFixed(3));
      const cierreBase = Number(p.cierre_base);

      const estaDentro = actualClose >= p10 && actualClose <= p90;
      if (estaDentro) dentro++;

      const errorCentro = Math.abs(actualClose - p50);
      const errorRW = Math.abs(actualClose - cierreBase);

      errorMedioCentro += errorCentro;
      errorMedioPaseoAleatorio += errorRW;

      cases.push({
        fecha_publicacion: p.fecha_publicacion,
        fecha_base: p.fecha_base,
        fecha_objetivo: p.fecha_objetivo,
        p10: Number(p10.toFixed(4)),
        p50: Number(p50.toFixed(4)),
        p90: Number(p90.toFixed(4)),
        cierre: Number(actualClose.toFixed(4)),
        dentro: estaDentro,
      });
    }

    cases.sort((a, b) => b.fecha_publicacion.localeCompare(a.fecha_publicacion));
    const last60 = cases.slice(0, 60);

    result[tipo] = {
      desde: cases.length > 0 ? cases[cases.length - 1].fecha_publicacion : null,
      n,
      dentro,
      cobertura: n > 0 ? Number(((dentro / n) * 100).toFixed(1)) : null,
      error_medio_centro: n > 0 ? Number((errorMedioCentro / n).toFixed(4)) : null,
      error_medio_paseo_aleatorio: n > 0 ? Number((errorMedioPaseoAleatorio / n).toFixed(4)) : null,
      casos: last60,
    };
  }

  // prueba_historica block from research/v7/auditoria-real/resultados-diario-real.json
  const pruebaHistoricaRaw = JSON.parse(fs.readFileSync(PRUEBA_HISTORICA_PATH, "utf8"));
  const pruebaHistorica = {
    asset: "USD/PEN",
    horizonte: "1 día hábil (siguiente cierre)",
    periodo: pruebaHistoricaRaw.periodo,
    metodo: pruebaHistoricaRaw.metodo,
    k_recalculo_dias_habiles: pruebaHistoricaRaw.k_recalculo_dias_habiles,
    min_cortes_calibracion: pruebaHistoricaRaw.min_cortes_calibracion,
    cortes: pruebaHistoricaRaw.cortes,
    cortes_estables: pruebaHistoricaRaw.cortes_estables,
    cobertura_fuera_muestra: pruebaHistoricaRaw.fhs.global.cobertura,
    ancho_medio_pct_fuera_muestra: Number(pruebaHistoricaRaw.fhs.global.ancho_pct.toFixed(3)),
    por_anio: pruebaHistoricaRaw.fhs.por_anio.map((y) => ({
      anio: Number(y.anio),
      n: y.n,
      cobertura: Number(y.cobertura.toFixed(2)),
      ancho_pct: Number(y.ancho_pct.toFixed(3)),
    })),
  };

  // backtest_motor from current daily-forecasts.json
  const dailyForecasts = JSON.parse(fs.readFileSync(DAILY_FORECASTS_PATH, "utf8"));
  const pen = dailyForecasts.simbolos?.PEN;
  const backtestMotor = {};
  if (pen) {
    if (pen.manana?.backtest) {
      backtestMotor.manana = {
        cobertura_80_k_expansivo: pen.manana.backtest.cobertura_80_k_expansivo,
        cortes_evaluados: pen.manana.backtest.cortes_evaluados,
      };
    }
    if (pen.semana?.backtest) {
      backtestMotor.semana = {
        cobertura_80_k_expansivo: pen.semana.backtest.cobertura_80_k_expansivo,
        cortes_evaluados: pen.semana.backtest.cortes_evaluados,
      };
    }
  }

  return {
    actualizado: today,
    horizontes: result,
    prueba_historica: pruebaHistorica,
    backtest_motor: backtestMotor,
  };
}

// Fields that define a published range: if any of them changes, the entry is replaced
const CAMPOS_RANGO = [
  "fecha_base",
  "cierre_base",
  "horizonte_dias_habiles",
  "p10",
  "p50",
  "p90",
];

/**
 * Lima date (UTC-5) of a given instant, as YYYY-MM-DD.
 * @param {Date} fecha - Instant to convert
 * @returns {string} Lima date like "2026-11-10"
 */
export function fechaLima(fecha) {
  return new Date(fecha.getTime() - 5 * 60 * 60 * 1000).toISOString().slice(0, 10);
}

/**
 * Instant of registration in UTC, as YYYY-MM-DDTHH:MM:SSZ (without milliseconds).
 * @param {Date} fecha - Instant to format
 * @returns {string} UTC timestamp like "2026-11-10T11:50:29Z"
 */
export function registradoUtc(fecha) {
  return fecha.toISOString().replace(/\.\d{3}Z$/, "Z");
}

/**
 * Opening of the target day: 09:00 in Lima (14:00 UTC). From that moment the entry is frozen.
 * @param {string} fechaObjetivo - Target date as YYYY-MM-DD
 * @returns {Date} Opening instant
 */
function aperturaDiaObjetivo(fechaObjetivo) {
  return new Date(`${fechaObjetivo}T14:00:00Z`);
}

/**
 * Builds the pronosticos-dolar.json from the latest daily-forecasts.json.
 * Rule: for every key tipo|fecha_objetivo the book keeps the last version registered BEFORE
 * 09:00 in Lima (14:00 UTC) of the target day. From that moment the entry is frozen: it is
 * neither added nor changed.
 * Handles both old format (horizonte, fecha_base) and new format (tipo, fecha_publicacion).
 * @param {Object} dailyForecasts - Content of data/daily-forecasts.json
 * @param {Array<Object>} existingPronosticos - Current book
 * @param {Object} opciones - { ahora }: instant of the run (defaults to now)
 * @returns {Array<Object>} The updated pronosticos array
 */
export function buildPronosticosFromDaily(dailyForecasts, existingPronosticos = [], { ahora = new Date() } = {}) {
  // Normalize existing entries to new format
  const normalizedExisting = existingPronosticos.map((p) => {
    if (p.tipo && p.fecha_publicacion) {
      return p; // Already new format
    }
    // Old format: convert horizonte to tipo, fecha_base to fecha_publicacion
    const tipoMap = { h1: "manana", h2: "manana", h5: "semana", h6: "semana", h8: "semana" };
    return {
      tipo: tipoMap[p.horizonte] || p.horizonte,
      fecha_publicacion: p.fecha_base,
      fecha_base: p.fecha_base,
      cierre_base: p.cierre_base,
      horizonte_dias_habiles: p.horizonte_dias_habiles || (p.horizonte === "h1" ? 1 : p.horizonte === "h2" ? 2 : p.horizonte === "h5" ? 5 : p.horizonte === "h6" ? 6 : 8),
      fecha_objetivo: p.fecha_objetivo,
      p10: p.p10,
      p50: p.p50,
      p90: p.p90,
    };
  });

  const pen = dailyForecasts.simbolos?.PEN;

  const momento = ahora instanceof Date ? ahora : new Date(ahora);
  const fechaPublicacion = fechaLima(momento);
  const registro = registradoUtc(momento);

  for (const tipo of ["manana", "semana"]) {
    const bloque = pen?.[tipo];
    if (!bloque) continue;

    // The target day already started: the entry stays frozen, nothing is added or changed
    if (momento >= aperturaDiaObjetivo(bloque.fecha_objetivo)) continue;

    const nueva = {
      tipo,
      fecha_publicacion: fechaPublicacion,
      fecha_base: pen.fecha_ultimo_cierre,
      cierre_base: Number(pen.ultimo_cierre.toFixed(4)),
      horizonte_dias_habiles: bloque.horizonte_dias_habiles,
      fecha_objetivo: bloque.fecha_objetivo,
      p10: Number(bloque.p10.toFixed(4)),
      p50: Number(bloque.p50.toFixed(4)),
      p90: Number(bloque.p90.toFixed(4)),
      registrado_utc: registro,
    };

    const indice = normalizedExisting.findIndex(
      (p) => p.tipo === tipo && p.fecha_objetivo === bloque.fecha_objetivo
    );

    if (indice === -1) {
      normalizedExisting.push(nueva);
      continue;
    }

    // Same key: replace only if the published values changed, otherwise leave the entry as is
    const previa = normalizedExisting[indice];
    const cambio = CAMPOS_RANGO.some((campo) => previa[campo] !== nueva[campo]);
    if (cambio) normalizedExisting[indice] = nueva;
  }

  // Book order: by fecha_objetivo ascending and, on the same date, manana before semana
  const tipoOrder = { manana: 1, semana: 2 };
  return normalizedExisting.sort((a, b) => {
    const dateCmp = (a.fecha_objetivo || "").localeCompare(b.fecha_objetivo || "");
    if (dateCmp !== 0) return dateCmp;
    return (tipoOrder[a.tipo] || 99) - (tipoOrder[b.tipo] || 99);
  });
}

async function main() {
  // Load daily-forecasts.json
  if (!fs.existsSync(DAILY_FORECASTS_PATH)) {
    console.error(`Archivo no encontrado: ${DAILY_FORECASTS_PATH}`);
    process.exit(1);
  }
  const dailyForecasts = JSON.parse(fs.readFileSync(DAILY_FORECASTS_PATH, "utf8"));

  // Load existing pronosticos-dolar.json
  let existingPronosticos = [];
  if (fs.existsSync(PRONOSTICOS_PATH)) {
    existingPronosticos = JSON.parse(fs.readFileSync(PRONOSTICOS_PATH, "utf8"));
  }

  // Build updated pronosticos (the run instant decides what can still be registered)
  const updatedPronosticos = buildPronosticosFromDaily(dailyForecasts, existingPronosticos, {
    ahora: new Date(),
  });

  // Save pronosticos-dolar.json
  const clavesAntes = new Set(existingPronosticos.map((p) => `${p.tipo}|${p.fecha_objetivo}`));
  const nuevas = updatedPronosticos.filter(
    (p) => !clavesAntes.has(`${p.tipo}|${p.fecha_objetivo}`)
  ).length;
  fs.writeFileSync(PRONOSTICOS_PATH, `${JSON.stringify(updatedPronosticos, null, 2)}\n`);
  console.log(`Pronósticos dólar guardados en ${PRONOSTICOS_PATH} (${updatedPronosticos.length} entradas, ${nuevas} nuevas)`);

  // Load BCRP official series
  if (!fs.existsSync(BCRP_PATH)) {
    console.error(`Archivo no encontrado: ${BCRP_PATH}`);
    process.exit(1);
  }
  const bcrp = JSON.parse(fs.readFileSync(BCRP_PATH, "utf8"));
  const officialSerie = bcrp.series?.PEN?.serie || [];

  // Evaluate
  const result = evaluatePublishedForecasts(updatedPronosticos, officialSerie);

  // Save aciertos-dolar.json
  fs.writeFileSync(OUTPUT_PATH, `${JSON.stringify(result, null, 2)}\n`);
  console.log(`Aciertos dólar guardados en ${OUTPUT_PATH}`);
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  main().catch((err) => {
    console.error("Error en aciertos-dolar:", err);
    process.exit(1);
  });
}